function ThemeContractPreview({theme}: {theme?: ColorTheme}) {
  const sdk = useApplicationSDK(), root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!root.current) return;
    const mounted = mountThemeExample(root.current, sdk, {theme});
    return () => mounted.dispose();
  }, [sdk, theme]);
  return <div ref={root} className="detail-preview-canvas" data-example-id="theme.dom"/>;
}

export function hasLiveExample(exampleId: string) {
  return exampleId === 'theme.dom' || Object.hasOwn(exampleRenderers, exampleId);
}

export function ComponentLivePreview({exampleId, theme}: {exampleId: string; theme?: ColorTheme}) {
  if (exampleId === 'theme.dom') return <ThemeContractPreview theme={theme}/>;
  const Example = exampleRenderers[exampleId];
  return Example ? <div className="detail-preview-canvas" data-example-id={exampleId}><Suspense fallback={<div role="status"><Skeleton active rows={2}/><span>加载示例…</span></div>}><Example/></Suspense></div> : null;
}
